<script setup lang="ts">
import type { Product } from '../shared'
import { ArrowLeft, ArrowRight, ShoppingBag, Trash2, Minus, Plus } from 'lucide-vue-next'
import { formatPrice } from '../shared'
const { items, update } = useCart()
const { data: products } = await useFetch<Product[]>('/api/products')
const lines = computed(() => items.value.map(item => ({ ...item, product: products.value?.find(p => p.id === item.id) })).filter(line => line.product))
const total = computed(() => lines.value.reduce((sum: number, line: { product?: Product; quantity: number }) => sum + (line.product?.price || 0) * line.quantity, 0))
useSeoMeta({ title: 'سبد خرید | پیله پاتری' })
</script>
<template><div class="container cart-page"><div class="page-header"><span class="eyebrow">YOUR BASKET</span><h1>سبد خرید شما</h1><p>چیزهای قشنگی انتخاب کرده‌اید.</p></div><div v-if="!lines.length" class="empty-state"><ShoppingBag :size="38" :stroke-width="1" style="margin:auto"/><h2>سبد خریدتان هنوز خالی است</h2><p>شاید وقتش رسیده یک چیز دوست‌داشتنی پیدا کنید.</p><NuxtLink to="/products" class="btn">رفتن به فروشگاه <ArrowLeft :size="16"/></NuxtLink></div><div v-else class="cart-layout"><div class="cart-items"><div v-for="line in lines" :key="line.id" class="cart-line"><NuxtLink :to="'/products/'+line.product!.slug" class="cart-image"><img :src="line.product!.image" :alt="line.product!.name"/></NuxtLink><div class="cart-line-info"><NuxtLink :to="'/products/'+line.product!.slug" class="line-name">{{ line.product!.name }}</NuxtLink><span class="line-price">{{ formatPrice(line.product!.price) }} تومان</span><div class="line-actions"><div class="mini-quantity"><button aria-label="کاهش تعداد" @click="update(line.id,line.quantity-1)"><Minus :size="13"/></button><span>{{ line.quantity }}</span><button aria-label="افزایش تعداد" :disabled="line.quantity>=line.product!.stock" @click="update(line.id,line.quantity+1)"><Plus :size="13"/></button></div><button class="remove" aria-label="حذف محصول" @click="update(line.id,0)"><Trash2 :size="16"/></button></div></div><div class="line-total">{{ formatPrice(line.product!.price*line.quantity) }} <small>تومان</small></div></div><NuxtLink to="/products" class="text-link continue"><ArrowRight :size="16"/> ادامه‌ی خرید</NuxtLink></div><aside class="cart-summary"><h2>خلاصه‌ی سفارش</h2><div class="summary-row"><span>جمع محصولات</span><span>{{ formatPrice(total) }} تومان</span></div><div class="summary-row"><span>هزینه‌ی ارسال</span><span>هماهنگی پس از ثبت سفارش</span></div><div class="summary-total"><span>مبلغ قابل پرداخت</span><strong>{{ formatPrice(total) }} <small>تومان</small></strong></div><NuxtLink to="/checkout" class="btn checkout-btn">ادامه و ثبت سفارش <ArrowLeft :size="17"/></NuxtLink><p>پرداخت امن از طریق درگاه زرین‌پال</p></aside></div></div></template>
<style scoped>.cart-page{padding-bottom:110px}.cart-layout{display:grid;grid-template-columns:1.7fr 1fr;gap:70px;align-items:start}.cart-line{display:flex;gap:22px;border-bottom:1px solid var(--line);padding:22px 0;position:relative}.cart-line:first-child{padding-top:0}.cart-image{width:116px;height:124px;flex:none;background:var(--cream)}.cart-image img{width:100%;height:100%;object-fit:cover}.cart-line-info{display:flex;flex-direction:column;align-items:flex-start;padding-top:5px}.line-name{font-weight:500;font-size:16px}.line-price{font-size:12px;color:var(--muted);margin-top:9px}.line-actions{margin-top:auto;display:flex;align-items:center;gap:18px}.mini-quantity{height:33px;border:1px solid var(--line);display:flex;align-items:center}.mini-quantity button{background:none;border:0;width:30px;display:grid;place-items:center}.mini-quantity button:disabled{opacity:.3}.mini-quantity span{font-size:12px;min-width:20px;text-align:center}.remove{border:0;background:none;color:#9b9d93}.line-total{margin-right:auto;font-size:13px;align-self:center;white-space:nowrap}.line-total small{font-size:11px}.continue{margin-top:33px}.cart-summary{background:#e9ebea;padding:33px}.cart-summary h2{font-size:18px;font-weight:500;margin:0 0 28px}.summary-row{display:flex;justify-content:space-between;gap:10px;font-size:12px;color:#777b70;padding:11px 0}.summary-total{border-top:1px solid #cccabe;display:flex;justify-content:space-between;align-items:center;margin-top:15px;padding:24px 0;font-size:13px}.summary-total strong{font-size:18px;font-weight:500}.summary-total small{font-size:11px}.checkout-btn{width:100%}.cart-summary p{text-align:center;font-size:11px;color:var(--muted);margin:18px 0 0}@media(max-width:850px){.cart-layout{gap:30px}}@media(max-width:650px){.cart-page{padding-bottom:65px}.cart-layout{grid-template-columns:1fr}.cart-image{width:88px;height:100px}.cart-line{gap:13px}.line-name{font-size:13px}.line-total{position:absolute;left:0;top:25px;font-size:11px}.cart-summary{padding:25px}}</style>
